#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;
const int SIZE = 4096;

void transform(vector<long long> &a) {  // XOR Walsh-Hadamard transform (unnormalized)
    for (int width = 1; width < SIZE; width *= 2)
        for (int start = 0; start < SIZE; start += 2 * width)
            for (int i = start; i < start + width; i++) {
                long long x = a[i], y = a[i + width];
                a[i] = x + y;
                a[i + width] = x - y;
            }
}

long long power(long long base, long long e) {
    long long r = 1;
    base %= MOD;
    for (; e > 0; e >>= 1, base = base * base % MOD)
        if (e & 1) r = r * base % MOD;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> freq(SIZE, 0);
        bool duplicate = false;
        for (int i = 0; i < n; i++) {
            int v;
            cin >> v;
            duplicate |= freq[v] > 0;
            freq[v]++;
        }
        if (duplicate) {  // some pair XORs to 0
            cout << 0 << "\n";
            continue;
        }
        transform(freq);
        for (auto &x : freq) x *= x;
        transform(freq);  // freq[v] / SIZE = ordered pairs with XOR v
        long long answer = 1;
        for (int v = 1; v < SIZE; v++) answer = answer * power(v, freq[v] / SIZE / 2) % MOD;
        cout << answer << "\n";
    }
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static final long MOD = 1000000007L;
    static final int SIZE = 4096;

    static void transform(long[] a) { // XOR Walsh-Hadamard transform (unnormalized)
        for (int width = 1; width < SIZE; width *= 2)
            for (int start = 0; start < SIZE; start += 2 * width)
                for (int i = start; i < start + width; i++) {
                    long x = a[i], y = a[i + width];
                    a[i] = x + y;
                    a[i + width] = x - y;
                }
    }

    static long power(long base, long e) {
        long r = 1;
        base %= MOD;
        for (; e > 0; e >>= 1, base = base * base % MOD)
            if ((e & 1) == 1) r = r * base % MOD;
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int t = nextInt();
        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            int n = nextInt();
            long[] freq = new long[SIZE];
            boolean duplicate = false;
            for (int i = 0; i < n; i++) {
                int v = nextInt();
                duplicate |= freq[v] > 0;
                freq[v]++;
            }
            if (duplicate) { // some pair XORs to 0
                out.append(0).append('\n');
                continue;
            }
            transform(freq);
            for (int i = 0; i < SIZE; i++) freq[i] *= freq[i];
            transform(freq); // freq[v] / SIZE = ordered pairs with XOR v
            long answer = 1;
            for (int v = 1; v < SIZE; v++) answer = answer * power(v, freq[v] / SIZE / 2) % MOD;
            out.append(answer).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

const mod = 1000000007
const size = 4096

func transform(a []int64) { // XOR Walsh-Hadamard transform (unnormalized)
	for width := 1; width < size; width *= 2 {
		for start := 0; start < size; start += 2 * width {
			for i := start; i < start+width; i++ {
				x, y := a[i], a[i+width]
				a[i], a[i+width] = x+y, x-y
			}
		}
	}
}

func power(base, e int64) int64 {
	r := int64(1)
	base %= mod
	for ; e > 0; e >>= 1 {
		if e&1 == 1 {
			r = r * base % mod
		}
		base = base * base % mod
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	t := int(nextInt())
	for ; t > 0; t-- {
		n := int(nextInt())
		freq := make([]int64, size)
		duplicate := false
		for i := 0; i < n; i++ {
			v := nextInt()
			if freq[v] > 0 {
				duplicate = true
			}
			freq[v]++
		}
		if duplicate { // some pair XORs to 0
			w.WriteString("0\n")
			continue
		}
		transform(freq)
		for i := range freq {
			freq[i] *= freq[i]
		}
		transform(freq) // freq[v] / size = ordered pairs with XOR v
		answer := int64(1)
		for v := 1; v < size; v++ {
			answer = answer * power(int64(v), freq[v]/size/2) % mod
		}
		w.WriteString(strconv.FormatInt(answer, 10) + "\n")
	}
}
